Remetente: {{$json.From || $json.from || $json.headers?.from || ''}}
Assunto: {{$json.Subject || $json.subject || $json.headers?.subject || ''}}
Corpo: {{$json.textPlain || $json.textHtml || $json.snippet || $json.body || ''}}

Categorias permitidas: Trabalho, Financeiro, Urgente, Newsletter, Cursos, IA, Publicidade, Spam/Suspeito.

Formato obrigatório:
{"categoria":"Trabalho|Financeiro|Urgente|Newsletter|Cursos|IA|Publicidade|Spam/Suspeito","resumo":"uma frase curta em português","confianca":0.9}

parameters.jsCode:
const input = $input.first().json;
const original = $('Preparar Dados do Email').first().json;

// Captura a resposta do Agent em vários formatos possíveis do n8n/LangChain
let raw =
  input.output ??
  input.text ??
  input.response ??
  input.result ??
  input.message ??
  input.content ??
  input.data ??
  input;

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

raw = raw.trim();

// Remove markdown, caso o modelo envie ```json
raw = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

// Se vier texto junto com JSON, extrai o primeiro objeto JSON completo
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  raw = jsonMatch[0];
}

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  // Fallback inteligente para quando o modelo devolver JSON cortado/incompleto
  const rawLower = raw.toLowerCase();
  let categoriaDetectada = 'Trabalho';

  if (
    rawLower.includes('spam') ||
    rawLower.includes('suspeito') ||
    rawLower.includes('phishing') ||
    rawLower.includes('golpe')
  ) {
    categoriaDetectada = 'Spam/Suspeito';
  } else if (
    rawLower.includes('urgente') ||
    rawLower.includes('imediato') ||
    rawLower.includes('hoje') ||
    rawLower.includes('atraso')
  ) {
    categoriaDetectada = 'Urgente';
  } else if (
    rawLower.includes('financeiro') ||
    rawLower.includes('boleto') ||
    rawLower.includes('pagamento') ||
    rawLower.includes('nota fiscal') ||
    rawLower.includes('cobrança') ||
    rawLower.includes('faturamento')
  ) {
    categoriaDetectada = 'Financeiro';
  } else if (
    rawLower.includes('curso') ||
    rawLower.includes('aula') ||
    rawLower.includes('treinamento') ||
    rawLower.includes('webinar') ||
    rawLower.includes('certificado')
  ) {
    categoriaDetectada = 'Cursos';
  } else if (
    rawLower.includes('"ia"') ||
    rawLower.includes('inteligência artificial') ||
    rawLower.includes('vertex ai') ||
    rawLower.includes('gemini') ||
    rawLower.includes('openai') ||
    rawLower.includes('claude') ||
    rawLower.includes('agente de ia') ||
    rawLower.includes('machine learning') ||
    rawLower.includes('llm')
  ) {
    categoriaDetectada = 'IA';
  } else if (
    rawLower.includes('publicidade') ||
    rawLower.includes('promoção') ||
    rawLower.includes('oferta') ||
    rawLower.includes('desconto') ||
    rawLower.includes('cupom')
  ) {
    categoriaDetectada = 'Publicidade';
  } else if (
    rawLower.includes('newsletter') ||
    rawLower.includes('novidades') ||
    rawLower.includes('notícias') ||
    rawLower.includes('atualização')
  ) {
    categoriaDetectada = 'Newsletter';
  }

  parsed = {
    categoria: categoriaDetectada,
    resumo: 'A IA retornou uma resposta incompleta, mas a categoria foi identificada parcialmente.',
    confianca: 0.3
  };
}

const categoriasPermitidas = [
  'Trabalho',
  'Financeiro',
  'Urgente',
  'Newsletter',
  'Cursos',
  'IA',
  'Publicidade',
  'Spam/Suspeito'
];

if (!categoriasPermitidas.includes(parsed.categoria)) {
  parsed.categoria = 'Trabalho';
}

if (!parsed.resumo) {
  parsed.resumo = 'E-mail recebido para análise e acompanhamento.';
}

const labelMap = {
  Trabalho: 'REPLACE_LABEL_ID_TRABALHO',
  Financeiro: 'REPLACE_LABEL_ID_FINANCEIRO',
  Urgente: 'REPLACE_LABEL_ID_URGENTE',
  Newsletter: 'REPLACE_LABEL_ID_NEWSLETTER',
  Cursos: 'REPLACE_LABEL_ID_CURSOS',
  IA: 'REPLACE_LABEL_ID_IA',
  Publicidade: 'REPLACE_LABEL_ID_PUBLICIDADE',
  'Spam/Suspeito': 'REPLACE_LABEL_ID_SPAM_SUSPEITO'
};

const gmailLabelId = labelMap[parsed.categoria];

if (!gmailLabelId) {
  throw new Error(`Categoria sem label configurada: ${parsed.categoria}`);
}

const gmailLabelIds = [gmailLabelId];

if (parsed.categoria === 'Urgente') {
  gmailLabelIds.push('STARRED');
}

// Evita erro no Telegram quando o remetente vem como: Nome <email@gmail.com>
const fromSeguro = String(original.from || 'remetente desconhecido')
  .replace(/</g, '(')
  .replace(/>/g, ')');

const categoriaSegura = String(parsed.categoria || 'Trabalho')
  .replace(/</g, '(')
  .replace(/>/g, ')');

const resumoSeguro = String(parsed.resumo || 'E-mail recebido para análise e acompanhamento.')
  .replace(/</g, '(')
  .replace(/>/g, ')');

const categoriasComRascunho = ['Financeiro', 'Urgente', 'Trabalho'];
const criaRascunho = categoriasComRascunho.includes(parsed.categoria);

return [
  {
    json: {
      messageId: original.messageId,
      threadId: original.threadId,
      from: original.from,
      subject: original.subject,
      categoria: parsed.categoria,
      resumo: parsed.resumo,
      confianca: parsed.confianca ?? null,
      gmailLabelId,
      gmailLabelIds,
      isUrgente: parsed.categoria === 'Urgente',
      criaRascunho,
      rawIaResponse: raw,
      originalAgentInput: input,
      telegramMessage: `📧 Novo e-mail de ${fromSeguro} classificado como ${categoriaSegura}. Resumo: ${resumoSeguro}${criaRascunho ? ' 📝 Um rascunho de resposta será criado no Gmail para revisão.' : ''}`
    }
  }
];

const normalizado = $('Normalizar Retorno da IA').first().json;
const original = $('Preparar Dados do Email').first().json;

const categoriasComRascunho = ['Financeiro', 'Urgente', 'Trabalho'];

if (!categoriasComRascunho.includes(normalizado.categoria)) {
  return [];
}

function extractEmail(from) {
  const value = String(from || '').trim();
  const match = value.match(/<([^>]+)>/);
  if (match) return match[1].trim();
  const emailMatch = value.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return emailMatch ? emailMatch[0] : value;
}

function encodeHeader(value) {
  const str = String(value || 'Sem assunto');
  if (/^[\x00-\x7F]*$/.test(str)) return str;
  return `=?UTF-8?B?${Buffer.from(str, 'utf8').toString('base64')}?=`;
}

function base64Url(value) {
  return Buffer.from(value, 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

const to = extractEmail(normalizado.from || original.from);
const subjectOriginal = normalizado.subject || original.subject || 'Sem assunto';
const subject = /^re:/i.test(subjectOriginal) ? subjectOriginal : `Re: ${subjectOriginal}`;

const respostas = {
  Financeiro: `Olá,\n\nRecebi o e-mail referente ao assunto financeiro e vou verificar as informações.\n\nCaso seja necessário algum retorno adicional, entrarei em contato.\n\nAtt.\nRenato`,
  Urgente: `Olá,\n\nRecebi sua mensagem e vou tratar esse assunto com prioridade.\n\nRetorno assim que possível.\n\nAtt.\nRenato`,
  Trabalho: `Olá,\n\nRecebi sua mensagem e vou analisar as informações.\n\nAssim que possível, retorno com uma posição.\n\nAtt.\nRenato`
};

const body = respostas[normalizado.categoria] || respostas.Trabalho;

const mime = [
  `To: ${to}`,
  `Subject: ${encodeHeader(subject)}`,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: 8bit',
  '',
  body
].join('\r\n');

const message = {
  raw: base64Url(mime)
};

if (normalizado.threadId || original.threadId) {
  message.threadId = normalizado.threadId || original.threadId;
}

return [
  {
    json: {
      to,
      subject,
      categoria: normalizado.categoria,
      draftReplyText: body,
      draftBody: {
        message
      }
    }
  }
];
